import{_ as a,a0 as p,w as u,s as g,ao as n,I as s,x as e,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在Ubuntu下安裝Google雲端硬盤客户端 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu下安裝Google雲端硬盤客户端 | LCTT (201309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu下安裝Google雲端硬盤客户端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu下安裝Google雲端硬盤客户端 | LCTT (201309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201309/How to Install a Google Drive Client on Ubuntu","title":"如何在Ubuntu下安裝Google雲端硬盤客户端","tag":"201309","desc":""},"relativePath":"201309/How to Install a Google Drive Client on Ubuntu.md","filePath":"[post].md"}'),r={name:"201309/How to Install a Google Drive Client on Ubuntu.md"};function m(d,t,b,G,v,f){const o=p("Link");return u(),g("div",null,[t[16]||(t[16]=n(`<h1 id="如何在ubuntu下安裝google雲端硬盤客户端" tabindex="-1">如何在Ubuntu下安裝Google雲端硬盤客户端 <a class="header-anchor" href="#如何在ubuntu下安裝google雲端硬盤客户端" aria-label="Permalink to “如何在Ubuntu下安裝Google雲端硬盤客户端”">​</a></h1><p>以下教程將為所有的Ubuntu用户講授如何在你們的運行正常的Ubuntu上安裝名為Grive的非官方Google雲端硬盤客户端。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Install-a-Google-Drive-Client-on-Ubuntu-381532-2.jpg" alt="img"></p><p>正如你所知，Google（大概討厭Linux用户）沒有為其優秀的Google雲端硬盤提供Linux客户端。但是不用擔心，隨着開源社區擁有了一些像Lorenzo Breda一樣的天才人物，他們為Linux開發了一個叫做 Grive的非官方的Google雲盤客户端。</p><p>在我們實際安裝之前，我們提醒你Grive應用還處於開發的早期階段，仍舊有一些侷限性，例如對多重父級的文件及文件夾的支持以及下載Google文檔的能力.</p><p>另外，我們應該提及的是Grive是一個命令列客户端並且沒有GUI（圖形用户界面），因此，這次安裝我們將使用其他Linux大神們製作的工具，叫做Grive Tools，它將在你的Ubuntu機器上自動下載、編譯和安裝最新版本的Grive.</p><p>Grive Tools支持以下的Ubuntu發行版：Ubuntu 12.10 (Quantal Quetzal), Ubuntu 13.04 (Raring Ringtail),和Ubuntu 13.10 (Saucy Salamander).</p><p>###安裝依賴庫</p><p>這是一個簡單的步驟，只要求你在Unity Dash上搜索並打開終端，然後將以下的代碼粘貼在終端窗口上：</p><pre><code>sudo apt-get install -y git cmake build-essential libgcrypt11-dev libjson0-dev libcurl4-openssl-dev libexpat1-dev libboost-filesystem-dev li    bboost-program-options-dev binutils-dev libboost-test-dev libqt4-dev libyajl-dev expect zenity gksu libnotify-bin
</code></pre><p>敲擊回車鍵後，當提示輸入密碼時鍵入密碼並再一次敲擊回車鍵開始進入安裝過程，需要注意的是可能有一些依賴包已經由你之前的應用程序安裝好了。</p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/small/googledriveubuntu-small_001.png" alt="img"></p><p>###安裝Grive Tools和Grive</p>`,13)),s("p",null,[t[1]||(t[1]=e("在",-1)),l(o,{href:"http://linux.softpedia.com/get/Utilities/Grive-Tools-102298.shtml"},{default:i(()=>[...t[0]||(t[0]=[e("這裏",-1)])]),_:1}),t[2]||(t[2]=e("下載正確的Grive Tools包並保存在你的桌面上，下載完成後雙擊它，此時Ubuntu軟件中心將打開，這樣你就可以輕鬆容易的安裝該應用了。",-1))]),t[17]||(t[17]=n('<p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/small/googledriveubuntu-small_002a.png" alt="img"></p><p>一旦安裝完成，在Unity Dash上搜索Grive Tools並打開。Grive Tools將要求你輸入你的密碼，鍵入你的密碼並點擊OK，然後Grive Tools將開始下載文件和配置最新版本的Grive，這將會花費你一些時間。</p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/small/googledriveubuntu-small_003.png" alt="img"></p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/small/googledriveubuntu-small_004.png" alt="img"></p><p>###在Grive上配置Google雲端硬盤</p><p>既然Google雲端硬盤Linux客户端已經安裝完畢，為了讓它可以訪問你的Google雲端賬號，我們需要對它進行配置，當你看到下面的對話框時請單擊&quot;Next&quot;按鈕。</p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/small/googledriveubuntu-small_005.png" alt="img"></p><p>一個web瀏覽器或標籤將被打開，要求您登錄到您的Google賬號（如果你尚未登入）並授權給該應用去訪問你的Google雲端硬盤，單擊藍色的&quot;Accept&quot;按鈕後你將可以看到Google認證碼，你需要將該認證碼複製並且粘貼在Grive設置對話框上。</p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/small/googledriveubuntu-small_006.png" alt="img"></p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/small/googledriveubuntu-small_007.png" alt="img"></p><p>就是這樣！你的Google雲端硬盤上的文件將根據你的Google賬號立即下載到並放置到你的家目錄下的&quot;Google Drive&quot;文件夾下。同步時你將可以看到一個桌面通知。</p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/small/googledriveubuntu-small_008.png" alt="img"></p><p>如果你在Unity Dash上搜索&quot;Google Drive&quot;（搜索時不加引號），你將可以看到一個Google雲端硬盤的圖標，你可以將該圖標拖拖動到Unity啓動器上，在Unity啓動器上右擊Google雲端硬盤圖標可以快速的同步到你的Google雲端硬盤上或者訪問你的本地文件夾。</p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/small/googledriveubuntu-small_009.png" alt="img"></p><p>如果您對於教程還有問題，儘管在下面寫下評論。</p>',15)),s("p",null,[t[5]||(t[5]=e("本文由 ",-1)),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[3]||(t[3]=[e("LCTT",-1)])]),_:1}),t[6]||(t[6]=e(" 原創翻譯，",-1)),l(o,{href:"http://linux.cn/portal.php"},{default:i(()=>[...t[4]||(t[4]=[e("Linux中國",-1)])]),_:1}),t[7]||(t[7]=e(" 榮譽推出。",-1))]),s("p",null,[t[11]||(t[11]=e("譯者：",-1)),l(o,{href:"http://linux.cn/space/luny"},{default:i(()=>[...t[8]||(t[8]=[e("Luny",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),l(o,{href:"http://linux.cn/space/caroline"},{default:i(()=>[...t[9]||(t[9]=[e("Caroline",-1)])]),_:1}),t[13]||(t[13]=e("，",-1)),l(o,{href:"http://linux.cn/space/wxy"},{default:i(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=e("via: ",-1)),l(o,{href:"http://news.softpedia.com/news/How-to-Install-a-Google-Drive-Client-on-Ubuntu-381532.shtml"},{default:i(()=>[...t[14]||(t[14]=[e("http://news.softpedia.com/news/How-to-Install-a-Google-Drive-Client-on-Ubuntu-381532.shtml",-1)])]),_:1})])])}const w=a(r,[["render",m]]);export{x as __pageData,w as default};
